// function transformUser(user)
// Agar user nahi: null
// Agar user.name nahi: null
// Warna { fullName, age } return karo

solution:
function transformUser(user) {
  if (!user) return null
  if (!user.name) return null
  return {
    fullName: user.name.toUpperCase(),
    age: user.age || 0
  }
}
